import { registerRenderer } from '../registry/stages.js';
export const render = (ctx) => {
    const errors = ctx.header.config_errors.length;
    return [
        '# setup',
        '',
        'First-run conversation: learn what this session can reach, propose a repo configuration, and write it only when the user says so.',
        '',
        '## 1. Diagnose',
        '',
        'Run the doctor and read it back to the user in plain words: what was inferred (with evidence), which config layers loaded, which roles are wired, the vault and build health.',
        errors ? `The current config has ${errors} problem(s) listed in the header; mention them first.` : 'The current config loads cleanly.',
        '',
        '```harness',
        'system doctor { }',
        '```',
        '',
        '## 2. Roles',
        '',
        'List every tool name visible in this session (the MCP tools you can call) and paste them into `system roles`; it maps them onto the roles by name heuristics and returns the unmapped ones. Confirm or correct the mapping with the user.',
        '',
        '```harness',
        'system roles { "tools": ["<every visible tool name>"] }',
        '```',
        '',
        '## 3. Questions',
        '',
        '- reviewbot: is a review bot installed on the repo? Which tool reports its status and threads?',
        '- kits: which kits should load (for example web-ui for browser repos)? They must be findable on the kit search path.',
        '- environments: which urls exist for sut, reference and production, and what env-var prefix holds their credentials?',
        '',
        '## 4. Proposal',
        '',
        'Merge the answers into the doctor proposal (`system config` with mode propose), show the full YAML to the user, and revise until it reads right.',
        '',
        '```harness',
        'system config { "mode": "propose" }',
        'system config { "mode": "write", "yaml": "<approved yaml>" }',
        '```',
        '',
        '## 5. Write',
        '',
        'Call `system config` with `"mode": "write"` and the approved text only after the user confirms; never write, overwrite or post anything before that confirmation.',
    ].join('\n');
};
registerRenderer('setup', render);
